import type { SortType, UserRole, UserSortBy } from '~/client';
import { ShieldUserIcon, UserCogIcon, UserRoundIcon, FileUserIcon } from 'lucide-vue-next';

interface UserRoleEntry {
  name: string;
  icon: Component;
}

export const userRoles: Record<UserRole, UserRoleEntry> = {
  canvasser: { name: 'Canvasser', icon: UserRoundIcon },
  manager: { name: 'Manager', icon: UserCogIcon },
  admin: { name: 'Admin', icon: ShieldUserIcon },
  subcontractor_canvasser: { name: 'Subcontractor Canvasser', icon: FileUserIcon },
};

export function getUserRole(role: UserRole): UserRoleEntry {
  return userRoles[role] ?? { name: snakeCaseToCapitalizedCase(role), icon: UserRoundIcon };
}

export const roleIcon = (role?: UserRole | null): Component => (role ? getUserRole(role).icon : UserRoundIcon);

export const userRolesItems: SelectItem<UserRole>[] = Object.entries(userRoles).map(([value, { name }]) => ({
  value: value as UserRole,
  name,
}));

export const usersSortByOptions: SelectItem<`${UserSortBy}|${SortType}`>[] = [
  { name: 'Name (desc)', value: 'name|desc' },
  { name: 'Name (asc)', value: 'name|asc' },
  { name: 'Email (desc)', value: 'email|desc' },
  { name: 'Email (asc)', value: 'email|asc' },
];
